import{_ as t,o as s,c as i,a3 as a,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/schueler/tutorials-offener-ganztag-merkmale-erfassen.png",p=JSON.parse('{"title":"Ganztag und Betreuungsangebote erfassen","description":"","frontmatter":{"title":"Ganztag und Betreuungsangebote erfassen","source_pageid":356,"source_revision":6958},"headers":[],"relativePath":"schild3/schueler/eintragung-der-schueler-im-offenen-ganztag-tutorial.md","filePath":"schild3/schueler/eintragung-der-schueler-im-offenen-ganztag-tutorial.md"}'),l={name:"schild3/schueler/eintragung-der-schueler-im-offenen-ganztag-tutorial.md"};function u(d,r,g,h,c,m){return s(),i("div",null,[...r[0]||(r[0]=[a('<h1 id="ganztag-und-betreuungsangebote-erfassen" tabindex="-1">Ganztag und Betreuungsangebote erfassen <a class="header-anchor" href="#ganztag-und-betreuungsangebote-erfassen" aria-label="Permalink to &quot;Ganztag und Betreuungsangebote erfassen&quot;">​</a></h1><p>Ordnen Sie Schülerinnen und Schüler dem offenen Ganztag oder anderen Betreuungsangeboten zu. Je nach Angebot werden Organisationsform und besondere Merkmale unterschiedlich erfasst.</p><h2 id="offener-ganztag" tabindex="-1">Offener Ganztag <a class="header-anchor" href="#offener-ganztag" aria-label="Permalink to &quot;Offener Ganztag&quot;">​</a></h2><p>Für Grundschulen mit offenem Ganztag ist für jeden Schüler im offenen Ganztag die Organisationsform <em>&quot;offener Ganztag&quot;</em> auf dem <em><strong>Reiter Akt. Halbjahr</strong></em> einzutragen.</p><p>Es sind <em><strong>keine weiteren Merkmale</strong></em> zu hinterlegen. Vorhandene Merkmale sollten gelöscht werden.</p><h2 id="schule-von-8-bis-1-dreizehn-plus-und-ahnliche" tabindex="-1">Schule von 8 bis 1, Dreizehn Plus und ähnliche <a class="header-anchor" href="#schule-von-8-bis-1-dreizehn-plus-und-ahnliche" aria-label="Permalink to &quot;Schule von 8 bis 1, Dreizehn Plus und ähnliche&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-offener-ganztag-merkmale-erfassen.png"><img src="'+o+'" alt="Nehmen Sie Merkmale für Ihre Schule auf." loading="lazy"></a></p><p><em>Nehmen Sie Merkmale für Ihre Schule auf.</em></p><p>Für Schülerinnen und Schüler, die nicht am offenen Ganztagsangebot teilnehmen, ist auf dem <em><strong>Reiter</strong></em> <em><strong>Akt. Halbjahr ➜ Allgemeine Angaben</strong></em> die Organisationsform <em>&quot;Halbtagsunterricht&quot;</em> einzustellen.</p><p>Tragen Sie die Betreuung zusätzlich unter <strong>Individualdaten II ➜ Besondere Merkmale</strong> ein. Wir empfehlen dort nur einen aktuellen Eintrag ohne Datumsangaben.</p><p>Bereiten Sie die benötigten Merkmale unter <strong>Verwaltung ➜ Schule ➜ Weitere Angaben ➜ Merkmale</strong> vor. Erst dann stehen sie bei den Schülerinnen und Schülern zur Auswahl.</p>',11),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Solche Eintragungen werden in SchILD-NRW nicht über die "),e("em",null,"Individualdaten I"),n(" direkt gesetzt, sondern aus dem jeweils aktuellen Abschnitt eingelesen.")])],-1),a('<h2 id="gruppenprozesse" tabindex="-1">Gruppenprozesse <a class="header-anchor" href="#gruppenprozesse" aria-label="Permalink to &quot;Gruppenprozesse&quot;">​</a></h2><p>Sie können die Organisationsform über einen Gruppenprozess setzen. Wählen Sie den <em><strong>Gruppenprozess</strong></em> <em><strong>Individualdaten ändern ➜ Individualdaten I.</strong></em> Sie können in der Rubrik <em><strong>Aktuelle Laufbahndaten</strong></em> die <em><strong>Klassen-Organisationsform</strong></em> gruppenweise setzen.</p><p>Merkmale für Halbtagskinder können ebenfalls über einen Gruppenprozess gesetzt werden. <em><strong>Gruppenprozess</strong></em> <em><strong>Individualdaten ändern ➜ Individualdaten II.</strong></em> Sie können in der Rubrik <em><strong>Sonstiges</strong></em> das passende Merkmal setzen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Eintragung_der_Sch%C3%BCler_im_offenen_Ganztag_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6958.</p>',5)])])}const b=t(l,[["render",u]]);export{p as __pageData,b as default};
